import './style.css'
import { api, streamChat, type ChatReference, type CreditOrder, type DocumentFile, type DocumentTask, type KnowledgeBase, type StudyAnswer, type StudyQuestion, type User } from './api.ts'

type Route = { name: string; id?: number }
type ToastKind = 'success' | 'error' | 'info'
type ChatMessage = { role: 'user' | 'assistant'; content: string; references?: ChatReference[]; pending?: boolean; error?: boolean }
const app = document.querySelector<HTMLDivElement>('#app')!
const tokenKey = 'learnhub_token'
const state: { user: User | null; knowledgeBases: KnowledgeBase[]; documents: DocumentFile[]; tasks: DocumentTask[]; boundDocuments: DocumentFile[]; boundLoadedFor: number | null; balance: number; selectedKnowledgeBaseId: number | null; selectedDocumentIds: number[]; chatMessages: ChatMessage[]; studyQuestions: StudyQuestion[]; studyAnswers: Record<number, StudyAnswer>; studyLibrary: StudyQuestion[]; studyLibraryTotal: number; studyLibraryPage: number; studyLibraryPages: number; studyQuestionType: string; studySelectedIds: number[]; studyView: 'bank' | 'generate' | 'practice'; studyLoadedFor: number | null; studyLibraryLoading: boolean; studyLibraryError: string | null; loading: boolean; activeModal: string | null; toast: { message: string; kind: ToastKind } | null; order: CreditOrder | null } = { user: null, knowledgeBases: [], documents: [], tasks: [], boundDocuments: [], boundLoadedFor: null, balance: 0, selectedKnowledgeBaseId: null, selectedDocumentIds: [], chatMessages: [], studyQuestions: [], studyAnswers: {}, studyLibrary: [], studyLibraryTotal: 0, studyLibraryPage: 1, studyLibraryPages: 1, studyQuestionType: '', studySelectedIds: [], studyView: 'bank', studyLoadedFor: null, studyLibraryLoading: false, studyLibraryError: null, loading: false, activeModal: null, toast: null, order: null }

function escapeHtml(value: unknown): string { return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;') }
function formatDate(value?: string): string { if (!value) return '刚刚'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value.slice(0, 10) : new Intl.DateTimeFormat('zh-CN', { month: 'short', day: 'numeric' }).format(date) }
function formatDateTime(value?: string): string { if (!value) return '刚刚'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('zh-CN', { month: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(date) }
function formatSize(bytes?: number): string { if (!bytes) return '0 KB'; return bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1024 / 1024).toFixed(1)} MB` }
function initials(user?: User | null): string { return (user?.nickname || user?.username || '林').slice(0, 1).toUpperCase() }
function currentRoute(): Route { const raw = window.location.hash.replace(/^#\/?/, '') || 'overview'; const [name, id] = raw.split('/'); return { name, id: id && /^\d+$/.test(id) ? Number(id) : undefined } }
function navigate(path: string): void { window.location.hash = `#/${path.replace(/^\//, '')}` }
function isAuthed(): boolean { return Boolean(localStorage.getItem(tokenKey)) }
function notify(message: string, kind: ToastKind = 'info'): void { state.toast = { message, kind }; render(); window.setTimeout(() => { if (state.toast?.message === message) { state.toast = null; render() } }, 3200) }
function icon(symbol: string, className = ''): string { return `<span class="icon ${className}" aria-hidden="true">${symbol}</span>` }
function statusLabel(status?: string): string { const map: Record<string, string> = { UPLOADED: '已上传', PARSING: '解析中', PARSED: '可用', SUCCESS: '已完成', FAILED: '失败', CREATED: '待支付', PAID: '已支付' }; return map[status || ''] || status || '未知' }
function statusClass(status?: string): string { const lowered = (status || '').toLowerCase(); if (lowered.includes('fail')) return 'danger'; if (lowered === 'parsing') return 'warning'; if (lowered.includes('paid') || lowered.includes('success') || lowered.includes('parsed') || lowered.includes('upload')) return 'success'; return 'neutral' }
async function loadWorkspace(): Promise<void> { if (!isAuthed()) return; state.loading = true; render(); try { const [user, knowledgeBases, documents, balance] = await Promise.all([api.me(), api.knowledgeBases(), api.documents(), api.balance()]); state.user = user; state.knowledgeBases = knowledgeBases.records || []; state.documents = documents.records || []; state.balance = Number(balance || 0); if (!state.selectedKnowledgeBaseId && state.knowledgeBases[0]) state.selectedKnowledgeBaseId = state.knowledgeBases[0].id } catch (error) { notify(error instanceof Error ? error.message : '工作区加载失败', 'error') } finally { state.loading = false; render() } }
function pageTitle(route: Route): string { const titles: Record<string, string> = { overview: '总览', knowledge: '知识库', 'knowledge-detail': '知识库详情', chat: 'AI 对话', documents: '文档中心', study: 'AI 学习', credits: '额度与订单', profile: '个人资料' }; return titles[route.name] || '总览' }
function navItem(path: string, label: string, glyph: string, active: boolean): string { return `<a class="nav-item ${active ? 'active' : ''}" href="#/${path}" data-nav="${path}" aria-current="${active ? 'page' : 'false'}">${icon(glyph)}<span>${label}</span></a>` }
function layout(content: string, route: Route): string { const active = route.name === 'knowledge-detail' || route.name === 'chat' ? 'knowledge' : route.name; return `<div class="app-shell"><aside class="sidebar"><div class="brand-lockup"><div class="brand-mark">L</div><div><strong>LearnHub</strong><span>个人学习工作台</span></div></div><div class="workspace-switcher"><span class="avatar small">${initials(state.user)}</span><span class="workspace-user">${escapeHtml(state.user?.nickname || state.user?.username || '学习者')}</span>${icon('⌄', 'chevron')}</div><nav class="primary-nav" aria-label="主导航"><div class="nav-section-label">Workspace</div>${navItem('overview', '总览', '⌂', active === 'overview')}${navItem('knowledge', '知识库', '▤', active === 'knowledge')}${navItem('documents', '文档中心', '□', active === 'documents')}${navItem('study', 'AI 学习', '✦', active === 'study')}<div class="nav-section-label second">Account</div>${navItem('credits', '额度与订单', '◒', active === 'credits')}${navItem('profile', '个人资料', '◎', active === 'profile')}</nav><div class="sidebar-bottom"><a class="support-link" href="http://localhost:8080/swagger-ui/index.html" target="_blank" rel="noreferrer">${icon('↗')} API 文档</a><button class="logout-link" data-action="logout">${icon('↪')} 退出登录</button></div></aside><main class="main-content" id="main-content"><header class="topbar"><div class="breadcrumbs"><span>LearnHub</span><b>/</b><strong>${escapeHtml(pageTitle(route))}</strong></div><div class="topbar-actions"><span class="api-status"><i></i> API 已连接</span><button class="icon-button" aria-label="通知">♧<sup>2</sup></button><button class="avatar" data-nav="profile" title="个人资料">${initials(state.user)}</button></div></header><div class="page-content">${content}</div></main>${state.toast ? `<div class="toast ${state.toast.kind}">${icon(state.toast.kind === 'success' ? '✓' : state.toast.kind === 'error' ? '!' : 'i')} ${escapeHtml(state.toast.message)}</div>` : ''}${state.activeModal ? modal(state.activeModal) : ''}</div>` }

function renderAuth(): void { app.innerHTML = `<div class="auth-page"><div class="auth-visual"><div class="auth-brand"><div class="brand-mark">L</div><strong>LearnHub</strong></div><div class="auth-quote"><span class="eyebrow">YOUR KNOWLEDGE, IN MOTION</span><h1>把零散的资料，<em>变成真正的理解。</em></h1><p>一个安静、有秩序的 AI 学习空间。上传你的知识，和它对话，然后用练习把理解留下来。</p><div class="auth-stamp">${icon('✦')} “学习不是收藏更多，而是看见连接。”</div></div><div class="auth-visual-footer"><span>LEARNHUB / 2026</span><span>Built for deep work</span></div></div><div class="auth-panel"><div class="auth-panel-inner"><div class="mobile-auth-brand"><div class="brand-mark">L</div><strong>LearnHub</strong></div><div class="auth-tabs"><button class="auth-tab active" data-auth-tab="login">登录</button><button class="auth-tab" data-auth-tab="register">注册账号</button></div><div id="auth-form-wrap"></div><p class="auth-footnote">继续即表示你同意 LearnHub 的服务条款与隐私政策</p></div></div></div>`; renderAuthForm('login') }
function renderAuthForm(mode: 'login' | 'register'): void { const wrap = document.querySelector<HTMLDivElement>('#auth-form-wrap'); if (!wrap) return; const register = mode === 'register'; wrap.innerHTML = `<div class="auth-heading"><span class="eyebrow">${register ? 'START YOUR PRACTICE' : 'WELCOME BACK'}</span><h2>${register ? '建立你的学习空间' : '晚上好，开始学习吧'}</h2><p>${register ? '创建账号，给知识一个可以持续生长的地方。' : '登录后继续整理知识、向资料提问，或开始一次练习。'}</p></div><form class="auth-form" data-form="${register ? 'register' : 'login'}"><label>用户名<input name="username" autocomplete="username" placeholder="例如 learnhub" minlength="${register ? '3' : '1'}" maxlength="30" required /></label><label>密码<input name="password" type="password" autocomplete="${register ? 'new-password' : 'current-password'}" placeholder="至少 8 位字符" minlength="${register ? '8' : '1'}" maxlength="64" required /></label>${!register ? '<div class="form-helper"><label class="check-line"><input type="checkbox" /> 记住我</label><span>JWT 登录 · 安全连接</span></div>' : ''}<button class="button primary wide" type="submit">${register ? '创建我的账号' : '进入学习工作台'} ${icon('→')}</button></form><div class="auth-demo"><span></span><small>${register ? '用户名仅支持字母、数字和下划线' : '还没有账号？点击上方“注册账号”'}</small><span></span></div>` }
function overviewPage(): string { const kb = state.knowledgeBases[0]; const recent = state.documents.slice(0, 4); const userName = state.user?.nickname || state.user?.username || '同学'; return `<section class="hero-row"><div><span class="eyebrow">TUESDAY, SEPTEMBER 15</span><h1>Good evening, <em>${escapeHtml(userName)}</em>.</h1><p class="hero-copy">今天也给自己留一点时间，去理解那些真正重要的东西。</p></div><div class="hero-signal"><div class="signal-orbit"><span>72%</span><small>本周专注度</small></div><div><b>保持得很好</b><span>连续学习 4 天</span></div></div></section><section class="overview-grid"><div class="section-heading"><div><span class="eyebrow">YOUR SPACE</span><h2>知识正在这里变得有序</h2></div><button class="text-button" data-action="open-create-kb">新建知识库 ${icon('↗')}</button></div><div class="feature-grid"><article class="feature-card ink-card" data-nav="knowledge-detail" data-id="${kb?.id || ''}"><div class="card-topline"><span class="card-kicker">FEATURED KNOWLEDGE BASE</span><span class="round-arrow">↗</span></div><div class="feature-card-content"><div><h3>${escapeHtml(kb?.name || '创建你的第一个知识库')}</h3><p>${escapeHtml(kb?.description || '把课程、书籍和灵感放在一起，建立属于你的上下文。')}</p></div><div class="feature-meta"><span>${icon('□')} ${state.documents.length} 份文档</span><span>更新于 ${formatDate(kb?.createdAt)}</span></div></div><div class="card-lines"></div></article><article class="feature-card chat-card" data-action="open-chat" data-id="${kb?.id || ''}"><div class="card-topline"><span class="card-kicker">ASK YOUR NOTES</span><span class="chat-live"><i></i> READY</span></div><div class="chat-card-content"><div class="chat-orb">${icon('✦')}</div><div><h3>和你的资料<br /><em>聊一聊。</em></h3><p>从一个问题开始，答案会沿着你的知识脉络出现。</p></div></div><div class="chat-prompt">试着问：我应该如何理解这些内容？ <span>↗</span></div></article></div></section><section class="lower-grid"><article class="activity-panel"><div class="section-heading compact"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>最近发生的事</h2></div><button class="ghost-button" data-nav="documents">查看全部</button></div>${recent.length ? `<div class="activity-list">${recent.map((doc, index) => `<div class="activity-item"><span class="activity-marker ${index === 0 ? 'active' : ''}">${index === 0 ? '↑' : '·'}</span><div><b>${index === 0 ? '上传了新文档' : '文档已加入你的空间'}</b><span>${escapeHtml(doc.fileName)}</span></div><time>${formatDate(doc.createdAt)}</time></div>`).join('')}</div>` : `<div class="empty-state small"><div class="empty-icon">□</div><b>还没有活动记录</b><span>上传第一份文档，开始构建你的学习空间。</span></div>`}</article><article class="balance-panel"><div class="section-heading compact"><div><span class="eyebrow">LEARNHUB CREDITS</span><h2>额度余额</h2></div><button class="circle-button" data-nav="credits" aria-label="打开额度">↗</button></div><div class="balance-number">${state.balance.toFixed(2)}<small> credits</small></div><div class="balance-foot"><span>AI 对话每次消耗 1 credit</span><button class="text-button" data-nav="credits">充值 ${icon('→')}</button></div></article></section>` }
function knowledgePage(): string { return `<section class="page-intro"><div><span class="eyebrow">KNOWLEDGE BASES / ${String(state.knowledgeBases.length).padStart(2, '0')}</span><h1>你的知识，<em>有了自己的房间。</em></h1><p>按主题整理资料，交给 AI 检索，也交给自己反复理解。</p></div><button class="button primary" data-action="open-create-kb">${icon('+')} 新建知识库</button></section><div class="toolbar"><div class="search-field">${icon('⌕')}<input id="kb-search" placeholder="搜索知识库..." /><kbd>⌘ K</kbd></div><div class="view-toggle"><button class="selected">▦</button><button>☷</button></div></div>${state.knowledgeBases.length ? `<div class="kb-grid">${state.knowledgeBases.map((kb, index) => knowledgeCard(kb, index)).join('')}</div>` : emptyBlock('还没有知识库', '从创建一个小而具体的主题开始。', 'open-create-kb', '创建第一个知识库')}` }
function knowledgeCard(kb: KnowledgeBase, index: number): string { const colors = ['blue', 'coral', 'olive', 'violet']; return `<article class="kb-card ${colors[index % colors.length]}" data-nav="knowledge-detail" data-id="${kb.id}"><div class="kb-card-header"><span class="kb-index">0${index + 1}</span><span class="round-arrow">↗</span></div><div class="kb-illustration"><span class="illustration-ring"></span><span class="illustration-glyph">${index % 2 ? '⌁' : '✦'}</span></div><div class="kb-card-body"><h3>${escapeHtml(kb.name)}</h3><p>${escapeHtml(kb.description || '还没有描述，为它写下一句说明吧。')}</p><div class="kb-card-footer"><span>${icon('□')} ${state.documents.length} 份文档</span><time>${formatDate(kb.createdAt)}</time></div></div></article>` }
function detailPage(id: number): string { const kb = state.knowledgeBases.find((item) => item.id === id); if (!kb) return `<div class="empty-page"><div class="empty-icon">?</div><h2>知识库不存在</h2><button class="button secondary" data-nav="knowledge">返回知识库</button></div>`; const docs = state.boundLoadedFor === id ? state.boundDocuments : []; return `<section class="detail-header"><button class="back-button" data-nav="knowledge">← 返回知识库</button><div class="detail-title"><div class="detail-symbol">${icon('✦')}</div><div><span class="eyebrow">KNOWLEDGE BASE / 0${state.knowledgeBases.indexOf(kb) + 1}</span><h1>${escapeHtml(kb.name)}</h1><p>${escapeHtml(kb.description || '这是一段还没有被定义的知识旅程。')}</p></div></div><div class="detail-actions"><button class="button secondary" data-action="open-edit-kb" data-id="${kb.id}">编辑</button><button class="button primary" data-action="open-chat" data-id="${kb.id}">${icon('✦')} 开始对话</button></div></section><div class="detail-tabs"><button class="active">资料概览</button><button data-action="open-chat" data-id="${kb.id}">AI 对话</button><button data-action="open-study" data-id="${kb.id}">生成练习</button></div><div class="detail-layout"><section><div class="detail-stat-row"><div><span>资料数量</span><b>${docs.length}</b><small>份文档</small></div><div><span>创建时间</span><b>${formatDate(kb.createdAt)}</b><small>持续生长中</small></div><div><span>状态</span><b class="status-dot"><i></i> 已就绪</b><small>AI 可以开始检索</small></div></div><div class="panel-section"><div class="section-heading compact"><div><span class="eyebrow">SOURCE MATERIALS</span><h2>资料文件</h2></div><button class="button small-button secondary" data-action="open-upload">上传文档</button></div>${docs.length ? `<div class="doc-table">${docs.map((doc) => documentRow(doc, false)).join('')}</div>` : emptyBlock('还没有资料文件', '上传 PDF、Markdown 或文本文件，让知识库开始工作。', 'open-upload', '上传第一份文档')}</div><div class="panel-section"><div class="section-heading compact"><div><span class="eyebrow">PROCESSING LOG</span><h2>解析任务</h2></div><button class="ghost-button" data-action="refresh-tasks" data-id="${kb.id}">刷新状态</button></div><div id="task-list"><div class="empty-state small"><span>点击刷新查看解析任务</span></div></div></div></section><aside class="side-rail"><div class="side-note"><span class="eyebrow">NEXT STEP</span><h3>让资料回答问题。</h3><p>当文档解析完成后，可以直接和它们对话，也可以生成一组练习检验理解。</p><button class="button dark wide" data-action="open-chat" data-id="${kb.id}">打开 AI 对话 ${icon('↗')}</button></div><div class="side-actions"><button data-action="open-edit-kb" data-id="${kb.id}">${icon('✎')} 编辑信息</button><button data-action="open-bind" data-id="${kb.id}">${icon('⊕')} 管理文档绑定</button><button class="danger-text" data-action="delete-kb" data-id="${kb.id}">${icon('⌫')} 删除知识库</button></div></aside></div>` }
function documentRow(doc: DocumentFile, selectable: boolean): string { const checked = state.selectedDocumentIds.includes(doc.fileId); return `<div class="doc-row ${checked ? 'checked' : ''}">${selectable ? `<label class="row-check"><input type="checkbox" data-document-check="${doc.fileId}" ${checked ? 'checked' : ''} /><span></span></label>` : ''}<div class="file-icon ${fileType(doc.fileName)}">${fileType(doc.fileName).toUpperCase()}</div><div class="doc-name"><b>${escapeHtml(doc.fileName)}</b><span>${formatSize(doc.fileSize)} · ${escapeHtml(doc.sha256 ? `${doc.sha256.slice(0, 10)}…` : '已上传')}</span></div><span class="status ${statusClass(doc.status)}"><i></i>${statusLabel(doc.status)}</span><time>${formatDateTime(doc.createdAt)}</time><div class="row-actions"><button data-action="share-doc" data-id="${doc.fileId}" title="分享">↗</button><button data-action="delete-doc" data-id="${doc.fileId}" title="删除">⌫</button></div></div>` }
function fileType(fileName?: string): string { const ext = (fileName || '').split('.').pop()?.toLowerCase() || 'file'; return ['pdf', 'md', 'txt', 'docx'].includes(ext) ? ext : 'file' }
function documentsPage(): string { const docs = state.documents; return `<section class="page-intro"><div><span class="eyebrow">DOCUMENT CENTER / ${String(docs.length).padStart(2, '0')}</span><h1>所有资料，<em>一处管理。</em></h1><p>先上传，再绑定到一个或多个知识库。文档解析后，AI 才能真正读懂它们。</p></div><button class="button primary" data-action="open-upload">${icon('↑')} 上传文档</button></section><div class="document-summary"><div><span>全部文档</span><b>${docs.length}</b></div><div><span>可用于检索</span><b>${docs.filter((doc) => doc.status === 'PARSED' || doc.status === 'UPLOADED').length}</b></div><div><span>解析中</span><b>${docs.filter((doc) => doc.status === 'PARSING').length}</b></div><div><span>空间占用</span><b>${formatSize(docs.reduce((sum, doc) => sum + (doc.fileSize || 0), 0))}</b></div></div><div class="toolbar"><div class="search-field">${icon('⌕')}<input id="doc-search" placeholder="按文件名搜索..." /></div><div class="filter-select"><select id="doc-filter"><option value="all">全部状态</option><option value="PARSED">可用</option><option value="PARSING">解析中</option><option value="FAILED">失败</option></select></div></div><section class="document-panel">${docs.length ? `<div class="doc-table doc-table-header"><span>文件</span><span>状态</span><span>添加时间</span><span></span></div><div id="documents-list">${docs.map((doc) => documentRow(doc, false)).join('')}</div>` : emptyBlock('还没有文档', '上传课程笔记、书籍或项目资料，让 LearnHub 开始帮你整理。', 'open-upload', '上传文档')}</section>` }
function studyPage(): string {
  const kb = state.knowledgeBases.find((item) => item.id === state.selectedKnowledgeBaseId) || state.knowledgeBases[0]
  const view = state.studyView
  return `<section class="study-hub-head"><div><span class="eyebrow">STUDY HUB / ACTIVE RECALL</span><h1>把“看过”，<em>变成“会了”。</em></h1><p>回到已有题库继续练习，也可以基于你的知识库生成一组新的挑战。</p></div><div class="study-hub-mark"><span>✦</span><small>REVIEW<br />·<br />RECALL</small></div></section><div class="study-switcher"><button class="${view === 'bank' ? 'active' : ''}" data-study-view="bank"><span>01</span><b>我的题库</b><small>查看、筛选和继续练习</small></button><button class="${view === 'generate' ? 'active' : ''}" data-study-view="generate"><span>02</span><b>生成新题</b><small>从知识库创建新的练习</small></button>${view === 'practice' ? `<button class="active" data-study-view="practice"><span>03</span><b>正在练习</b><small>完成这一组题目</small></button>` : ''}</div>${view === 'bank' ? studyBankView(kb) : view === 'generate' ? studyGenerateView(kb) : studyPracticeView()}`
}
function studyBankView(kb?: KnowledgeBase): string {
  const selected = state.studySelectedIds.length
  return `<section class="study-bank"><div class="study-toolbar"><div><span class="eyebrow">QUESTION LIBRARY / ${String(state.studyLibraryTotal).padStart(2, '0')}</span><h2>已有题库</h2></div><div class="study-filters"><select data-study-filter="kb" aria-label="选择知识库">${state.knowledgeBases.map((item) => `<option value="${item.id}" ${item.id === kb?.id ? 'selected' : ''}>${escapeHtml(item.name)}</option>`).join('')}</select><select data-study-filter="type" aria-label="筛选题型"><option value="">全部题型</option><option value="SINGLE_CHOICE" ${state.studyQuestionType === 'SINGLE_CHOICE' ? 'selected' : ''}>单选题</option><option value="MULTIPLE_CHOICE" ${state.studyQuestionType === 'MULTIPLE_CHOICE' ? 'selected' : ''}>多选题</option></select></div></div>${state.studyLibraryLoading ? `<div class="study-loading"><span class="loading-spinner"></span><b>正在打开题库</b><small>从后端加载你已经生成的题目...</small></div>` : state.studyLibraryError ? `<div class="study-error"><div class="empty-icon">!</div><h3>题库暂时打不开</h3><p>${escapeHtml(state.studyLibraryError)}</p><button class="button secondary" data-action="retry-study-library">重新加载 ${icon('↻')}</button></div>` : state.studyLibrary.length ? `<div class="bank-actions"><label class="select-all"><input type="checkbox" data-study-select-all ${selected === state.studyLibrary.length ? 'checked' : ''} /> 全选本页</label><span>${selected ? `已选择 ${selected} 道题` : '选择题目后可连续练习'}</span><div><button class="button secondary small-button" data-action="delete-selected-study" ${selected ? '' : 'disabled'}>删除选中</button><button class="button primary small-button" data-action="start-selected-study" ${selected ? '' : 'disabled'}>开始练习 ${icon('→')}</button></div></div><div class="question-library">${state.studyLibrary.map((question, index) => studyLibraryRow(question, index)).join('')}</div>${studyPagination()}` : `<div class="practice-empty bank-empty"><div class="practice-mark">□</div><h2>题库还是空的。</h2><p>从“生成新题”开始，题目会自动保存到这里。之后你可以随时回来继续练习。</p><button class="button primary" data-study-view="generate">生成第一组题 ${icon('→')}</button></div>`}</section>`
}
function studyLibraryRow(question: StudyQuestion, index: number): string { const selected = state.studySelectedIds.includes(question.id); return `<article class="library-row ${selected ? 'selected' : ''}"><label class="library-check"><input type="checkbox" data-study-check="${question.id}" ${selected ? 'checked' : ''} /><span></span></label><span class="library-number">${String((state.studyLibraryPage - 1) * 12 + index + 1).padStart(2, '0')}</span><div class="library-content"><p>${escapeHtml(question.content)}</p><div><span>${question.options?.length || 0} 个选项</span><span>题目 #${question.id}</span></div></div><button class="library-open" data-action="open-study-question" data-id="${question.id}">查看并作答 ${icon('↗')}</button></article>` }
function studyPagination(): string { if (state.studyLibraryPages <= 1) return ''; return `<div class="study-pagination"><button data-action="study-page" data-page="${state.studyLibraryPage - 1}" ${state.studyLibraryPage <= 1 ? 'disabled' : ''}>←</button><span>第 ${state.studyLibraryPage} / ${state.studyLibraryPages} 页 · 共 ${state.studyLibraryTotal} 道题</span><button data-action="study-page" data-page="${state.studyLibraryPage + 1}" ${state.studyLibraryPage >= state.studyLibraryPages ? 'disabled' : ''}>→</button></div>` }
function studyGenerateView(kb?: KnowledgeBase): string { return `<section class="generate-view"><div class="generate-copy"><span class="eyebrow">NEW PRACTICE SET</span><h2>给自己一个<br /><em>更好的问题。</em></h2><p>选择知识库、题型和数量。生成后题目会保存到你的题库，随时可以回来继续做。</p><div class="generate-principle"><span>生成</span><i>→</i><span>回忆</span><i>→</i><span>反馈</span><i>→</i><span>进步</span></div></div><form class="study-generator" data-form="generate-study"><div class="generator-label"><span>01</span><b>选择知识库</b></div><label><select name="knowledgeBaseId" required>${state.knowledgeBases.map((item) => `<option value="${item.id}" ${item.id === kb?.id ? 'selected' : ''}>${escapeHtml(item.name)}</option>`).join('')}</select><small>题目会从这个知识库的资料中生成</small></label><div class="generator-label"><span>02</span><b>设置难度方向</b></div><label><select name="questionType"><option value="SINGLE_CHOICE">单选题</option><option value="MULTIPLE_CHOICE">多选题</option></select><small>先选择一种题型，生成后可以在题库中统一复习</small></label><div class="generator-label"><span>03</span><b>题目数量</b></div><label><div class="range-row"><input name="count" type="range" min="1" max="10" value="5" /><output>5 题</output></div><small>建议每次生成 5 道，保持一次练习的专注感</small></label><div class="generator-label"><span>04</span><b>聚焦主题 <em>可选</em></b></div><label><input name="topic" maxlength="200" placeholder="例如：Java 集合框架、第三章重点" /><small>留空则覆盖整个知识库</small></label><button class="button dark wide generate-submit" type="submit">${icon('✦')} 生成并开始练习</button></form></section>` }
function studyPracticeView(): string { const questions = state.studyQuestions; return `<section class="practice-view"><div class="practice-header"><div><button class="back-button" data-study-view="bank">← 返回题库</button><span class="eyebrow">CURRENT PRACTICE / ${questions.length} QUESTIONS</span><h2>专注完成这一组。</h2><p>每次只处理一个问题，先凭记忆作答，再看反馈。</p></div><div class="practice-score"><span>本次得分</span><b>${studyScore()}<small> / ${questions.length || 0}</small></b></div></div><div class="practice-list">${questions.length ? questions.map((question, index) => questionCard(question, index)).join('') : `<div class="empty-state">没有可练习的题目</div>`}</div></section>` }
function studyScore(): number { return Object.values(state.studyAnswers).filter((answer) => answer.correct).length }
function questionCard(question: StudyQuestion, index: number): string { const answer = state.studyAnswers[question.id]; const selected = answer?.selectedOptions || []; const multiple = question.questionType === 'MULTIPLE_CHOICE'; return `<article class="question-card ${answer ? (answer.correct ? 'answered correct' : 'answered incorrect') : ''}"><div class="question-topline"><span>QUESTION ${String(index + 1).padStart(2, '0')}</span><span>${multiple ? '多选题' : '单选题'} · ${answer ? (answer.correct ? '回答正确' : '再想想') : '未作答'}</span></div><h3>${escapeHtml(question.content)}</h3><div class="options-list">${question.options.map((option) => `<label class="option ${selected.includes(option.optionKey) ? 'selected' : ''} ${answer?.correctOptions.includes(option.optionKey) ? 'correct-option' : ''}"><input type="${multiple ? 'checkbox' : 'radio'}" name="question-${question.id}" value="${escapeHtml(option.optionKey)}" ${selected.includes(option.optionKey) ? 'checked' : ''} ${answer ? 'disabled' : ''} data-question-option="${question.id}" /><span class="option-key">${escapeHtml(option.optionKey)}</span><span>${escapeHtml(option.content)}</span></label>`).join('')}</div>${answer ? `<div class="answer-feedback ${answer.correct ? 'positive' : ''}"><b>${answer.correct ? '回答正确' : `正确答案：${answer.correctOptions.join('、')}`}</b><p>${escapeHtml(answer.analysis || '继续保持，下一题见。')}</p></div>` : `<button class="button secondary submit-answer" data-action="submit-answer" data-id="${question.id}">提交答案 ${icon('→')}</button>`}</article>` }
function chatPage(id: number): string { const kb = state.knowledgeBases.find((item) => item.id === id); if (!kb) return `<div class="empty-page"><div class="empty-icon">?</div><h2>请选择一个知识库</h2><button class="button secondary" data-nav="knowledge">返回知识库</button></div>`; return `<section class="chat-page"><header class="chat-header"><button class="back-button" data-nav="knowledge-detail" data-id="${id}">← ${escapeHtml(kb.name)}</button><div class="chat-header-center"><div class="detail-symbol small">${icon('✦')}</div><div><span class="eyebrow">KNOWLEDGE CHAT</span><h1>和 ${escapeHtml(kb.name)} 对话</h1></div></div><div class="chat-credit">${icon('◒')} ${state.balance.toFixed(0)} credits</div></header><div class="chat-body"><div class="chat-intro"><span class="eyebrow">YOUR MATERIAL, YOUR CONTEXT</span><h2>问一个具体的问题，<br /><em>让理解发生。</em></h2><p>回答只会来自“${escapeHtml(kb.name)}”中已经解析的资料。</p></div><div class="messages" id="messages">${state.chatMessages.length ? state.chatMessages.map(chatBubble).join('') : `<div class="chat-suggestions"><button data-suggestion="帮我总结这份知识库中最重要的三个概念">帮我总结最重要的三个概念 <span>↗</span></button><button data-suggestion="这些内容之间有什么联系？">这些内容之间有什么联系？ <span>↗</span></button><button data-suggestion="请出一道题检验我是否理解了">出一道题检验我的理解 <span>↗</span></button></div>`}</div></div><form class="chat-composer" data-form="chat" data-id="${id}"><textarea name="question" rows="1" placeholder="向你的知识库提问..." maxlength="1000" required></textarea><div class="composer-footer"><span>${icon('⌘')} Enter 发送 · Shift + Enter 换行</span><button class="send-button" type="submit" aria-label="发送">↗</button></div></form></section>` }
function chatBubble(message: ChatMessage): string { const classes = `message ${message.role}${message.error ? ' error' : ''}`; return `<div class="${classes}"><div class="message-avatar">${message.role === 'user' ? initials(state.user) : '✦'}</div><div class="message-content"><div class="message-meta">${message.role === 'user' ? '你' : message.error ? 'AI 提示' : 'LearnHub AI'} <time>${message.role === 'user' ? '刚刚' : message.error ? '未完成' : '根据你的资料'}</time></div><div class="message-text">${message.pending ? '<span class="typing"><i></i><i></i><i></i></span>' : escapeHtml(message.content).replaceAll('\n', '<br />')}</div>${message.references?.length ? `<div class="references"><span>资料引用</span>${message.references.map((reference) => `<small>${icon('□')} ${escapeHtml(reference.fileName)} · 片段 ${reference.chunkIndex >= 0 ? reference.chunkIndex : 'n/a'}</small>`).join('')}</div>` : ''}</div></div>` }
function creditsPage(): string { return `<section class="page-intro credits-intro"><div><span class="eyebrow">CREDITS / BILLING</span><h1>给好问题，<em>留一点余地。</em></h1><p>额度用于 AI 对话和练习生成。这里是模拟支付流程，方便本地开发与体验。</p></div><div class="credits-balance"><span>当前可用额度</span><b>${state.balance.toFixed(2)}</b><small>credits</small></div></section><section class="credit-layout"><div class="pricing-panel"><div class="section-heading compact"><div><span class="eyebrow">TOP UP</span><h2>选择充值额度</h2></div><span class="mini-note">1 次 AI 对话 = 1 credit</span></div><div class="credit-plans"><button data-credit="10"><strong>10</strong><span>credits</span><small>适合试用</small></button><button class="recommended" data-credit="50"><span class="recommend-label">最受欢迎</span><strong>50</strong><span>credits</span><small>适合持续学习</small></button><button data-credit="100"><strong>100</strong><span>credits</span><small>适合长期使用</small></button></div><form class="custom-credit" data-form="create-order"><label>自定义金额（元）<div class="money-input"><span>¥</span><input name="amount" type="number" step="0.01" min="0.01" placeholder="输入金额" /></div></label><button class="button primary" type="submit">创建模拟订单 ${icon('→')}</button></form></div><div class="credit-info"><div class="credit-card"><span class="eyebrow">LEARNHUB BALANCE</span><b>${state.balance.toFixed(2)}</b><span>credits available</span><div class="credit-card-symbol">◒</div></div><div class="credit-rules"><b>使用说明</b><span>AI 对话每次消耗 1 credit</span><span>生成练习按一次请求计费</span><span>支付回调可重复执行，不会重复入账</span></div></div></section>${state.order ? `<section class="order-panel"><div class="section-heading compact"><div><span class="eyebrow">LATEST ORDER</span><h2>订单已创建</h2></div><span class="status success"><i></i>${statusLabel(state.order.status)}</span></div><div class="order-row"><span>订单号 <b>${escapeHtml(state.order.orderNo)}</b></span><span>金额 <b>¥${Number(state.order.amount).toFixed(2)}</b></span><span>创建于 <b>${formatDateTime(state.order.createdAt)}</b></span><button class="button dark" data-action="simulate-payment">模拟支付并入账</button></div></section>` : ''}` }
function profilePage(): string { return `<section class="page-intro"><div><span class="eyebrow">ACCOUNT / PROFILE</span><h1>你的学习身份，<em>保持真实。</em></h1><p>这里展示当前登录账号信息和连接状态。</p></div></section><section class="profile-layout"><div class="profile-card"><div class="profile-cover"></div><div class="profile-content"><div class="large-avatar">${initials(state.user)}</div><h2>${escapeHtml(state.user?.nickname || state.user?.username || '学习者')}</h2><p>@${escapeHtml(state.user?.username || '')}</p><div class="profile-divider"></div><div class="profile-detail"><span>用户 ID</span><b>${state.user?.id ?? 'n/a'}</b></div><div class="profile-detail"><span>账号状态</span><b class="status success"><i></i> 已连接</b></div></div></div><div class="profile-notes"><div class="note-block"><span class="eyebrow">CONNECTED SYSTEM</span><h2>后端服务正常工作。</h2><p>LearnHub 前端通过本地代理连接到运行在 8080 端口的后端服务。认证令牌保存在当前浏览器会话中。</p><div class="connection-line"><i></i><span>localhost:8080</span><b>ONLINE</b></div></div><div class="note-block"><span class="eyebrow">QUICK ACCESS</span><div class="quick-links"><button data-nav="knowledge">${icon('▤')} 管理知识库 <span>→</span></button><button data-nav="documents">${icon('□')} 查看全部文档 <span>→</span></button><button data-nav="credits">${icon('◒')} 查看额度余额 <span>→</span></button></div></div></div></section>` }
function emptyBlock(title: string, description: string, action: string, label: string): string { return `<div class="empty-block"><div class="empty-icon">✦</div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(description)}</p><button class="button secondary" data-action="${action}">${label} ${icon('→')}</button></div>` }
function modal(name: string): string { const kb = state.knowledgeBases.find((item) => item.id === state.selectedKnowledgeBaseId); if (name === 'create-kb' || name === 'edit-kb') { const edit = name === 'edit-kb'; const editKb = kb; return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" onclick="event.stopPropagation()"><button class="modal-close" data-action="close-modal">×</button><span class="eyebrow">${edit ? 'EDIT KNOWLEDGE BASE' : 'NEW KNOWLEDGE BASE'}</span><h2>${edit ? '调整这个空间' : '创建一个新空间'}</h2><p>${edit ? '名称和描述会帮助你更快找到正确的上下文。' : '从一个具体主题开始，之后随时可以继续扩展。'}</p><form data-form="${edit ? 'edit-kb' : 'create-kb'}" data-id="${editKb?.id || ''}"><label>名称<input name="name" value="${escapeHtml(editKb?.name || '')}" maxlength="50" placeholder="例如：Java 基础" required /></label><label>描述 <span class="optional">可选</span><textarea name="description" maxlength="1000" rows="4" placeholder="它会帮助你记住这个空间的用途。">${escapeHtml(editKb?.description || '')}</textarea></label><button class="button primary wide" type="submit">${edit ? '保存修改' : '创建知识库'} ${icon('→')}</button></form></div></div>` } if (name === 'upload') return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" onclick="event.stopPropagation()"><button class="modal-close" data-action="close-modal">×</button><span class="eyebrow">ADD SOURCE MATERIAL</span><h2>上传一份新资料</h2><p>支持 PDF、Markdown、TXT 等常见格式。上传后可以绑定到任意知识库。</p><form data-form="upload"><label class="dropzone"><input name="file" type="file" accept=".pdf,.md,.txt,.doc,.docx" required /><span class="dropzone-icon">↑</span><b>选择文件或拖到这里</b><small>单个文件上传</small></label><button class="button primary wide" type="submit">开始上传 ${icon('→')}</button></form></div></div>`; if (name === 'bind') return `<div class="modal wide-modal" onclick="event.stopPropagation()"><button class="modal-close" data-action="close-modal">×</button><span class="eyebrow">MANAGE MATERIALS</span><h2>管理「${escapeHtml(kb?.name || '')}」的资料</h2><p>勾选需要绑定到这个知识库的文档。保存后 AI 会使用这些资料回答问题。</p><div class="bind-list">${state.documents.length ? state.documents.map((doc) => documentRow(doc, true)).join('') : '<div class="empty-state small"><span>先上传一份文档</span></div>'}</div><div class="modal-actions"><button class="button secondary" data-action="close-modal">取消</button><button class="button primary" data-action="save-bind" data-id="${kb?.id || ''}">保存绑定 ${icon('→')}</button></div></div>`; return '' }
function render(): void { if (!isAuthed()) { renderAuth(); return } const route = currentRoute(); let content = ''; if (route.name === 'overview') content = overviewPage(); else if (route.name === 'knowledge') content = knowledgePage(); else if (route.name === 'knowledge-detail' && route.id) content = detailPage(route.id); else if (route.name === 'chat' && route.id) content = chatPage(route.id); else if (route.name === 'documents') content = documentsPage(); else if (route.name === 'study') content = studyPage(); else if (route.name === 'credits') content = creditsPage(); else if (route.name === 'profile') content = profilePage(); else content = overviewPage(); app.innerHTML = layout(content, route); if (route.name === 'knowledge-detail' && route.id) { if (state.boundLoadedFor !== route.id) void loadBoundDocuments(route.id); else void loadTasks(route.id) }
if (route.name === 'study' && state.studyLoadedFor !== state.selectedKnowledgeBaseId && state.studyView === 'bank' && state.selectedKnowledgeBaseId) void loadStudyLibrary(state.selectedKnowledgeBaseId) }
async function loadStudyLibrary(id: number, page = 1): Promise<void> { if (state.studyLibraryLoading) return; state.studyLibraryLoading = true; state.studyLibraryError = null; state.studyLoadedFor = null; render(); try { const response = await api.studyQuestionPage(id, page, 12, state.studyQuestionType); state.studyLibrary = response?.records || []; state.studyLibraryTotal = Number(response?.total || 0); state.studyLibraryPage = Number(response?.current || page); state.studyLibraryPages = Number(response?.pages || 1); state.studyLoadedFor = id } catch (error) { state.studyLibrary = []; state.studyLibraryTotal = 0; state.studyLibraryError = error instanceof Error ? error.message : '题库加载失败'; state.studyLoadedFor = id } finally { state.studyLibraryLoading = false; render() } }
function normalizeQuestionType(value?: string): 'SINGLE_CHOICE' | 'MULTIPLE_CHOICE' { return String(value || '').toUpperCase().includes('MULTI') ? 'MULTIPLE_CHOICE' : 'SINGLE_CHOICE' }
async function hydrateStudyQuestion(question: StudyQuestion): Promise<StudyQuestion> { try { const detail = await api.questionDetail(question.id); return { ...question, questionType: normalizeQuestionType(detail.questionType), content: detail.content || question.content, options: detail.options?.map((option) => ({ optionKey: option.optionKey, content: option.content })) || question.options } } catch { return { ...question, questionType: normalizeQuestionType(question.questionType) } } }
async function loadBoundDocuments(id: number): Promise<void> { try { const response = await api.knowledgeBaseDocuments(id); state.boundDocuments = response.records || []; state.boundLoadedFor = id; render() } catch (error) { notify(error instanceof Error ? error.message : '资料加载失败', 'error') } }
async function loadTasks(id: number): Promise<void> { const target = document.querySelector<HTMLDivElement>('#task-list'); if (!target) return; try { const response = await api.tasks(id); state.tasks = response.records || []; target.innerHTML = state.tasks.length ? state.tasks.map((task) => `<div class="task-row"><span class="file-icon task">${icon('↺')}</span><div><b>${escapeHtml(task.fileName || `文件 #${task.fileId}`)}</b><span>${escapeHtml(task.type || 'DOCUMENT_PARSE')} · ${formatDateTime(task.createdAt)}</span></div><span class="status ${statusClass(task.status)}"><i></i>${statusLabel(task.status)}</span>${task.lastError ? `<small class="task-error">${escapeHtml(task.lastError)}</small>` : ''}</div>`).join('') : '<div class="empty-state small"><span>暂无解析任务记录</span></div>' } catch (error) { target.innerHTML = `<div class="empty-state small"><span>${escapeHtml(error instanceof Error ? error.message : '任务加载失败')}</span></div>` } }
async function handleAuth(form: HTMLFormElement): Promise<void> { const data = new FormData(form); const username = String(data.get('username') || ''); const password = String(data.get('password') || ''); const mode = form.dataset.form; const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]'); if (submit) submit.disabled = true; try { if (mode === 'register') { await api.register({ username, password }); notify('账号创建成功，请登录', 'success'); renderAuthForm('login') } else { const token = await api.login({ username, password }); localStorage.setItem(tokenKey, token.token); window.location.hash = '#/overview'; await loadWorkspace(); notify('欢迎回来，学习者', 'success') } } catch (error) { notify(error instanceof Error ? error.message : '操作失败', 'error') } finally { if (submit) submit.disabled = false } }
async function handleSubmit(form: HTMLFormElement): Promise<void> { const formName = form.dataset.form; const data = new FormData(form); const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]'); if (submit) submit.disabled = true; try { if (formName === 'create-kb') { const kb = await api.createKnowledgeBase({ name: String(data.get('name') || ''), description: String(data.get('description') || '') }); state.knowledgeBases.unshift(kb); state.selectedKnowledgeBaseId = kb.id; state.activeModal = null; render(); notify('知识库创建成功', 'success') } else if (formName === 'edit-kb') { const id = Number(form.dataset.id); const kb = await api.updateKnowledgeBase(id, { name: String(data.get('name') || ''), description: String(data.get('description') || '') }); state.knowledgeBases = state.knowledgeBases.map((item) => item.id === id ? kb : item); state.activeModal = null; render(); notify('知识库已更新', 'success') } else if (formName === 'upload') { const file = data.get('file'); if (!(file instanceof File)) throw new Error('请选择需要上传的文件'); const doc = await api.uploadDocument(file); state.documents.unshift(doc); state.activeModal = null; render(); notify('文档上传成功，正在解析', 'success') } else if (formName === 'generate-study') { const kbId = Number(data.get('knowledgeBaseId')); state.selectedKnowledgeBaseId = kbId; state.studyQuestions = await api.generateQuestions(kbId, { count: Number(data.get('count') || 5), topic: String(data.get('topic') || ''), questionType: String(data.get('questionType') || 'SINGLE_CHOICE') }); state.studyQuestions = await Promise.all(state.studyQuestions.map(hydrateStudyQuestion)); state.studyAnswers = {}; state.studyView = 'practice'; render(); notify(`已生成 ${state.studyQuestions.length} 道练习题`, 'success') } else if (formName === 'chat') await sendChat(form); else if (formName === 'create-order') { const amount = Number(data.get('amount')); if (!amount || amount < 0.01) throw new Error('请输入有效的充值金额'); state.order = await api.createOrder(amount); render(); notify('模拟订单已创建', 'success') } } catch (error) { notify(error instanceof Error ? error.message : '操作失败', 'error') } finally { if (submit) submit.disabled = false } }
async function sendChat(form: HTMLFormElement): Promise<void> { const id = Number(form.dataset.id); const textarea = form.querySelector<HTMLTextAreaElement>('textarea[name="question"]'); const question = textarea?.value.trim() || ''; if (!question) return; state.chatMessages.push({ role: 'user', content: question }); state.chatMessages.push({ role: 'assistant', content: '', pending: true }); if (textarea) textarea.value = ''; render(); const assistantIndex = state.chatMessages.length - 1; const showChatError = (message: string): void => { const assistant = state.chatMessages[assistantIndex]; if (!assistant) return; assistant.content = assistant.content ? `${assistant.content}\n\n${message}` : message; assistant.pending = false; assistant.error = true; renderMessagesOnly() }; try { await streamChat(id, question, { onReferences: (references) => { state.chatMessages[assistantIndex].references = references; renderMessagesOnly() }, onContent: (chunk) => { state.chatMessages[assistantIndex].content += chunk; state.chatMessages[assistantIndex].pending = false; renderMessagesOnly() }, onError: showChatError }) } catch (error) { showChatError(error instanceof Error ? error.message : '对话失败，请稍后重试') } }
function renderMessagesOnly(): void { const messages = document.querySelector<HTMLDivElement>('#messages'); if (messages) messages.innerHTML = state.chatMessages.map(chatBubble).join(''); messages?.scrollTo({ top: messages.scrollHeight, behavior: 'smooth' }) }
async function handleAction(element: HTMLElement): Promise<void> { const action = element.dataset.action; if (element.dataset.nav) { navigate(element.dataset.id ? `${element.dataset.nav}/${element.dataset.id}` : element.dataset.nav); return } if (action === 'logout') { localStorage.removeItem(tokenKey); state.user = null; state.chatMessages = []; render(); return } if (action === 'close-modal') { state.activeModal = null; render(); return } if (action === 'open-create-kb') { state.activeModal = 'create-kb'; render(); return } if (action === 'open-edit-kb') { state.selectedKnowledgeBaseId = Number(element.dataset.id); state.activeModal = 'edit-kb'; render(); return } if (action === 'open-upload') { state.activeModal = 'upload'; render(); return } if (action === 'open-bind') { const id = Number(element.dataset.id); state.selectedKnowledgeBaseId = id; try { const response = await api.knowledgeBaseDocuments(id); state.selectedDocumentIds = (response.records || []).map((doc) => doc.fileId) } catch { state.selectedDocumentIds = [] } state.activeModal = 'bind'; render(); return } if (action === 'retry-study-library') { if (state.selectedKnowledgeBaseId) void loadStudyLibrary(state.selectedKnowledgeBaseId, state.studyLibraryPage); return } if (action === 'open-study-question') { const id = Number(element.dataset.id); try { const question = await hydrateStudyQuestion(await api.question(id)); state.studyQuestions = [question]; state.studyAnswers = {}; state.studyView = 'practice'; state.selectedKnowledgeBaseId = question.knowledgeBaseId; if (currentRoute().name === 'study') render(); else navigate('study') } catch (error) { notify(error instanceof Error ? error.message : '题目加载失败', 'error') } return } if (action === 'delete-selected-study') { if (!state.studySelectedIds.length) return; if (!window.confirm(`确定删除选中的 ${state.studySelectedIds.length} 道题吗？`)) return; try { await api.deleteQuestions(state.studySelectedIds); state.studySelectedIds = []; await loadStudyLibrary(state.selectedKnowledgeBaseId || 0, state.studyLibraryPage); notify('选中题目已删除', 'success') } catch (error) { notify(error instanceof Error ? error.message : '删除失败', 'error') } return } if (action === 'start-selected-study') { const questions = state.studyLibrary.filter((question) => state.studySelectedIds.includes(question.id)); if (questions.length) { state.studyQuestions = await Promise.all(questions.map(hydrateStudyQuestion)); state.studyAnswers = {}; state.studyView = 'practice'; render() } return } if (action === 'study-page') { const page = Number(element.dataset.page); if (page > 0 && state.selectedKnowledgeBaseId) await loadStudyLibrary(state.selectedKnowledgeBaseId, page); return } if (action === 'open-chat') { const id = Number(element.dataset.id) || state.selectedKnowledgeBaseId || state.knowledgeBases[0]?.id; if (id) { state.selectedKnowledgeBaseId = id; navigate(`chat/${id}`) } return } if (action === 'open-study') { const id = Number(element.dataset.id) || state.selectedKnowledgeBaseId; if (id) state.selectedKnowledgeBaseId = id; navigate('study'); return } if (action === 'delete-kb') { const id = Number(element.dataset.id); if (!window.confirm('确定删除这个知识库吗？有文档绑定时后端会拒绝删除。')) return; try { await api.deleteKnowledgeBase(id); state.knowledgeBases = state.knowledgeBases.filter((kb) => kb.id !== id); navigate('knowledge'); notify('知识库已删除', 'success') } catch (error) { notify(error instanceof Error ? error.message : '删除失败', 'error') } return } if (action === 'delete-doc') { const id = Number(element.dataset.id); if (!window.confirm('确定删除这份文档吗？')) return; try { await api.deleteDocument(id); state.documents = state.documents.filter((doc) => doc.fileId !== id); render(); notify('文档已删除', 'success') } catch (error) { notify(error instanceof Error ? error.message : '删除失败', 'error') } return } if (action === 'share-doc') { try { const url = await api.shareDocument(Number(element.dataset.id)); await navigator.clipboard.writeText(url); notify('分享链接已复制', 'success') } catch (error) { notify(error instanceof Error ? error.message : '链接获取失败', 'error') } return } if (action === 'refresh-tasks') { await loadTasks(Number(element.dataset.id)); return } if (action === 'save-bind') { const id = Number(element.dataset.id); try { if (!state.selectedDocumentIds.length) throw new Error('至少选择一份文档；如需清空，请保留一份后再管理绑定'); await api.unbindDocuments(id, state.selectedDocumentIds); state.activeModal = null; state.boundLoadedFor = null; notify('资料绑定已保存', 'success'); render() } catch (error) { notify(error instanceof Error ? error.message : '保存失败', 'error') } return } if (action === 'submit-answer') { const id = Number(element.dataset.id); const options = Array.from(document.querySelectorAll<HTMLInputElement>(`[data-question-option="${id}"]:checked`)).map((input) => input.value); try { state.studyAnswers[id] = await api.submitAnswer(id, options); render(); notify(state.studyAnswers[id].correct ? '回答正确' : '已记录这次尝试', state.studyAnswers[id].correct ? 'success' : 'info') } catch (error) { notify(error instanceof Error ? error.message : '提交失败', 'error') } return } if (action === 'simulate-payment' && state.order) { try { await api.notifyPayment({ orderNo: state.order.orderNo, amount: Number(state.order.amount), tradeNo: `LOCAL-${Date.now()}` }); state.balance += Number(state.order.amount); state.order = { ...state.order, status: 'PAID', paidAt: new Date().toISOString() }; render(); notify('支付成功，额度已入账', 'success') } catch (error) { notify(error instanceof Error ? error.message : '支付回调失败', 'error') } } }
document.addEventListener('click', (event) => { const target = event.target as HTMLElement; const nav = target.closest<HTMLElement>('[data-nav]'); if (nav) { event.preventDefault(); void handleAction(nav); return } const action = target.closest<HTMLElement>('[data-action]'); if (action) { void handleAction(action); return } const authTab = target.closest<HTMLButtonElement>('[data-auth-tab]'); if (authTab) { document.querySelectorAll('[data-auth-tab]').forEach((tab) => tab.classList.remove('active')); authTab.classList.add('active'); renderAuthForm(authTab.dataset.authTab === 'register' ? 'register' : 'login'); return } const studyView = target.closest<HTMLElement>('[data-study-view]'); if (studyView) { state.studyView = (studyView.dataset.studyView as 'bank' | 'generate' | 'practice') || 'bank'; render(); if (state.studyView === 'bank' && state.selectedKnowledgeBaseId) void loadStudyLibrary(state.selectedKnowledgeBaseId); return } const suggestion = target.closest<HTMLButtonElement>('[data-suggestion]'); if (suggestion) { const textarea = document.querySelector<HTMLTextAreaElement>('.chat-composer textarea'); if (textarea) { textarea.value = suggestion.dataset.suggestion || ''; textarea.focus() } } const credit = target.closest<HTMLButtonElement>('[data-credit]'); if (credit) { const input = document.querySelector<HTMLInputElement>('.custom-credit input'); if (input) input.value = credit.dataset.credit || ''; input?.focus() } })
document.addEventListener('submit', (event) => { const form = event.target as HTMLFormElement; event.preventDefault(); if (form.dataset.form === 'login' || form.dataset.form === 'register') void handleAuth(form); else void handleSubmit(form) })
document.addEventListener('change', (event) => { const target = event.target as HTMLInputElement; if (target.dataset.studyCheck) { const id = Number(target.dataset.studyCheck); if (target.checked) state.studySelectedIds.push(id); else state.studySelectedIds = state.studySelectedIds.filter((item) => item !== id); target.closest('.library-row')?.classList.toggle('selected', target.checked) } if (target.hasAttribute('data-study-select-all')) { state.studySelectedIds = target.checked ? state.studyLibrary.map((question) => question.id) : []; render() } if (target.dataset.studyFilter === 'kb') { state.selectedKnowledgeBaseId = Number(target.value); state.studyLoadedFor = null; void loadStudyLibrary(state.selectedKnowledgeBaseId) } if (target.dataset.studyFilter === 'type') { state.studyQuestionType = target.value; if (state.selectedKnowledgeBaseId) void loadStudyLibrary(state.selectedKnowledgeBaseId) } if (target.dataset.documentCheck) { const id = Number(target.dataset.documentCheck); if (target.checked) state.selectedDocumentIds.push(id); else state.selectedDocumentIds = state.selectedDocumentIds.filter((item) => item !== id); target.closest('.doc-row')?.classList.toggle('checked', target.checked) } if (target.dataset.questionOption) target.closest('.option')?.classList.toggle('selected', target.checked) })
document.addEventListener('input', (event) => { const target = event.target as HTMLInputElement; if (target.matches('input[type="range"]')) { const output = target.parentElement?.querySelector('output'); if (output) output.textContent = `${target.value} 题` } })
document.addEventListener('keydown', (event) => { const target = event.target as HTMLTextAreaElement; if (target.matches('.chat-composer textarea') && event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); target.closest('form')?.requestSubmit() } })
window.addEventListener('hashchange', () => render())
window.addEventListener('learnhub:unauthorized', () => { localStorage.removeItem(tokenKey); state.user = null; renderAuth(); notify('登录已过期，请重新登录', 'error') })
if (isAuthed()) void loadWorkspace(); else render()
